// rings: a two-operator FM exciter that drops onto each note, into an eight-mode MODAL resonator. A fixed-point port
// of the float reference engine (rings.c in the port kit), with its exact constants (tables.h, generated by
// tools/gen_tables.py).
//
// Per 64-sample block:
//   FM core at 2x, in four 16-sample steps (the drop, BITE and the onset move per step, as in the reference)
//     -> half-band to 1x -> the two fixed 20.7 kHz low-passes -> keytracked high-pass (with the drive gain)
//     -> presence peak
//   -> MODAL: eight two-pole resonators (+ STRIKE at note-on), mixed with the dry drive
//   -> keytracked high-pass -> keytracked high shelf -> output, Q31 (gain 143: the loudest setting peaks near 1/8)
//
// The OP-XY gives a voice no note-off, so the stock amp envelope shapes the whole sound: the voice runs as the
// reference does at ATTACK 0 and SUSTAIN 1, struck at full strength. It keeps the reference's 3 ms eased onset.
//
// Everything after the FM core is linear, so the second fixed low-pass, which the reference runs after the modes,
// runs before them here, and STRIKE, which enters the modes, goes through it in its table instead (tables.h).
//
// Fixed point throughout: Q31 signals, coefficients made per note and per knob change from table-based sine, log2
// and exp2 (fixmath.h). No float, no division and no 64-bit arithmetic. Recursive filters and the modes keep the
// small quantities near their poles as the stored coefficients (2 + a1 and 1 - a2 rather than a1 and a2), so low
// notes keep their precision: a mode at 20 Hz has 2 - 2 r cos th = 8.7e-6, held to 1 part in 18,000.
#include "core.h"
#include "fixmath.h"

namespace rings {
namespace {

const unsigned STEP = 16;               // the reference's sub-block
const unsigned STEPS = opxy::block_frames / STEP;

inline i32 knob_word(i32 w) { return w < 0 ? 0 : w; }
inline i32 mul28(i32 a, i32 c) { return mul(a, c) * 8; }

// ---------------------------------------------------------------- filters (direct form I)
// The fixed 20.7 kHz low-pass: b0 (x + 2 x1 + x2) - a1 y1 - a2 y2.
inline i32 lowpass(Biquad& f, i32 x) {
    const i32 y = mul(LP_B0, x + 2 * f.x1 + f.x2) - mul30(f.y1, LP_A1) - mul(f.y2, LP_A2);
    f.x2 = f.x1; f.x1 = x; f.y2 = f.y1; f.y1 = y;
    return y;
}
// Keytracked high-pass: b0 (x - 2 x1 + x2) + (2 - e) y1 - (1 - h) y2, e = 2 + a1, h = 1 - a2.
inline i32 highpass(Biquad& f, i32 b0, const i32* c, i32 x) {
    const i32 y = mul(b0, x - 2 * f.x1 + f.x2) + 2 * f.y1 - f.y2 - mul30(f.y1, c[2]) + mul(f.y2, c[3]);
    f.x2 = f.x1; f.x1 = x; f.y2 = f.y1; f.y1 = y;
    return y;
}
// Presence peak (b1 = a1): (1 + p) x + (e - 2)(x1 - y1) + (1 - q) x2 - (1 - h) y2.
inline i32 presence(Biquad& f, const i32* c, i32 x) {
    const i32 d = f.x1 - f.y1;
    const i32 y = x + mul30(x, c[0]) - 2 * d + mul29(d, c[1]) + f.x2 - mul30(f.x2, c[2]) - f.y2 + mul(f.y2, c[3]);
    f.x2 = f.x1; f.x1 = x; f.y2 = f.y1; f.y1 = y;
    return y;
}
// High shelf: b0 x + b1 x1 + b2 x2 - a1 y1 - a2 y2.
inline i32 shelf(Biquad& f, const i32* c, i32 x) {
    const i32 y = mul29(x, c[0]) + mul28(f.x1, c[1]) + mul29(f.x2, c[2]) - mul30(f.y1, c[3]) - mul(f.y2, c[4]);
    f.x2 = f.x1; f.x1 = x; f.y2 = f.y1; f.y1 = y;
    return y;
}

// The half angle of a cutoff given as a phase increment (2^32 = the sample rate): h = sin(w0/2), k = cos(w0/2), Q31.
inline void half_angle(u32 inc, i32& h, i32& k) {
    h = sine(inc >> 1) * 2;
    k = cosine(inc >> 1) * 2;
}
// 1 / a0 for a0 in [1, 2), Q30 in, Q31 out.
inline i32 reciprocal(i32 a0_q30) { return exp2q(-log2q(a0_q30, 30), 31); }
// sign(n) |n| / d x 2^extra in Q`bits`: n and d in the same format, d > 0.
inline i32 ratio(i32 n, i32 ld, i32 lextra, int bits) {
    if (!n) return 0;
    const i32 v = exp2q(log2u(static_cast<u32>(absolute(n))) - ld + lextra, bits);
    return n < 0 ? -v : v;
}

// RBJ high-pass, Q 0.7: with s = 2hk, alpha = hk/Q, a0 = 1 + alpha: b0 = (1 - h^2)/a0, 2 + a1 = 2 (alpha + 2 h^2)/a0,
// 1 - a2 = 2 alpha/a0.
void setup_highpass(Voice& v, u32 inc) {
    i32 h, k; half_angle(inc, h, k);
    const i32 h2 = mul(h, h), al = mul30(mul(h, k), HP_INVQ);
    const i32 inv = reciprocal(half(al) + (1 << 30));
    const i32 b0 = mul(MAX - h2, inv);
    v.hp_c[0] = mul(b0, HP1_GAIN);
    v.hp_c[1] = b0;
    v.hp_c[2] = mul(half(al) + h2, inv) * 2;           // Q30
    v.hp_c[3] = mul(al, inv) * 2;                      // Q31
}
// RBJ peaking EQ, Q 0.8: alpha = hk/Q, a0 = 1 + alpha/A: b0 - 1 = alpha (A - 1/A)/a0, 2 + a1 = 2 (alpha/A + 2 h^2)/a0,
// 1 - b2 = alpha (A + 1/A)/a0, 1 - a2 = 2 alpha/(A a0).
void setup_presence(Voice& v, u32 inc) {
    i32 h, k; half_angle(inc, h, k);
    const i32 h2 = mul(h, h), al = mul30(mul(h, k), PK_INVQ);
    const i32 ala = mul(al, PK_A) * 2;                 // alpha A, Q30
    const i32 alb = mul(al, PK_AINV);                  // alpha / A, Q31
    const i32 inv = reciprocal(half(alb) + (1 << 30));
    v.pk_c[0] = mul(ala - half(alb), inv);             // Q30
    v.pk_c[1] = mul(half(alb) + h2, inv);              // Q29
    v.pk_c[2] = mul(half(alb) + ala, inv);             // Q30
    v.pk_c[3] = mul(alb, inv) * 2;                     // Q31
}
// RBJ high shelf, slope 1, with cos w0 = 1 - 2 h^2 and 2 sqrt(A) alpha = 2 sqrt(2A) hk; normalised by a0 in log2.
void setup_shelf(Voice& v, u32 inc) {
    i32 h, k; half_angle(inc, h, k);
    const i32 c = (1 << 30) - mul(h, h);               // cos w0, Q30
    const i32 sq = mul(HS_SQ, mul(h, k));              // Q28
    const i32 am1c = mul30(HS_AM1, c), ap1c = mul30(HS_AP1, c);   // Q28
    const i32 a0 = HS_AP1 - am1c + sq;
    const i32 la = log2u(static_cast<u32>(a0)), lA = log2q(HS_A, 29);
    v.hs_c[0] = ratio(HS_AP1 + am1c + sq, la, lA, 29);
    v.hs_c[1] = ratio(-(HS_AM1 + ap1c), la, lA + ONE_LOG, 28);
    v.hs_c[2] = ratio(HS_AP1 + am1c - sq, la, lA, 29);
    v.hs_c[3] = ratio(HS_AM1 - ap1c, la, ONE_LOG, 30);
    v.hs_c[4] = ratio(HS_AP1 - am1c - sq, la, 0, 31);
}

// ---------------------------------------------------------------- knobs
// A DROP lane: 0..1 along it, split at DROP_SPLIT, each side a power curve.
i32 lane(i32 x, i32 mid, i32 e1, i32 e2) {
    if (x <= DROP_SPLIT_Q31) {
        const i32 y = clamp(mul29(x, DROP_SPLIT_INV), 0, MAX);
        return y ? mul(mid, exp2q(mul29(log2q(y, 31), e1), 31)) : 0;
    }
    const i32 y = clamp(mul29(x - DROP_SPLIT_Q31, DROP_HI_INV), 0, MAX);
    return mid + mul(MAX - mid, y ? exp2q(mul29(log2q(y, 31), e2), 31) : 0);
}
void set_drop(Voice& v, i32 x) {
    i32 oct = SW_A0 + mul(SW_SPAN, lane(x, SW_MID, SW_E1, SW_E2));
    if (absolute(oct) < SW_DEAD) oct = 0;
    v.sweep_oct = oct;
    v.sweep_du = exp2q(L_DT_T0 - mul(L_T1_T0, lane(x, TM_MID, TM_E1, TM_E2)), 31);
}
void set_stretch(Voice& v, i32 x) {
    const i32 centred = x - 0x40000000;
    const i32 stretch = absolute(centred) < STRETCH_DEAD ? 0 : sar(centred, 6);   // 2 (x - 0.5), Q24
    const i32 st = exp2q(stretch, 29);                                           // 2^stretch, Q29
    for (unsigned k = 0; k < MODES; ++k) v.lrr[k] = mul29(L_RM[k], st) + L_SPREAD[k];
}
void set_modes(Voice& v, i32 x) {
    const i32 m7 = mul(x, 7 << 28);                 // 7 x, Q28: mode k is fed clamp(1 + 7x - k, 0, 1)
    v.wk[0] = MAX;
    for (unsigned k = 1; k < MODES; ++k) {
        const i32 w = clamp(m7 - static_cast<i32>(k - 1) * (1 << 28), 0, 1 << 28);
        v.wk[k] = w == (1 << 28) ? MAX : w * 8;
    }
}

// ---------------------------------------------------------------- note set-up
// Keytracked filters for a pitch.
void setup_pitch(Voice& v, u32 inc) {
    v.setup_inc = inc;
    setup_highpass(v, static_cast<u32>(mul(static_cast<i32>(inc), HP_RATIO)));
    setup_presence(v, inc <= static_cast<u32>(INC_LIMIT) / INC_PRESENCE_RATIO
        ? inc * INC_PRESENCE_RATIO : static_cast<u32>(INC_LIMIT));
    setup_shelf(v, inc <= static_cast<u32>(INC_LIMIT) / INC_SHELF_RATIO
        ? inc * INC_SHELF_RATIO : static_cast<u32>(INC_LIMIT));
}
// Where the modes sit: frequency, edge fade and pole, for the pitch and STRETCH.
void setup_modes(Voice& v) {
    const i32 linc = log2u(v.setup_inc);
    v.high = 0;
    for (unsigned k = 0; k < MODES; ++k) {
        const i32 l = linc + v.lrr[k];
        v.lfk[k] = clamp(l, L_INC_20HZ, L_INC_NY);
        i32 edge = 0;
        u32 fk = 0;
        if (l < L_INC_NY) {
            fk = exp2u(l);
            if (fk > static_cast<u32>(INC_20HZ)) {
                edge = fk < 2u * static_cast<u32>(INC_20HZ)
                    ? exp2q(log2u(fk - static_cast<u32>(INC_20HZ)) - L_INC_20HZ, 31) : MAX;
                if (l > L_INC_NY09)
                    edge = mul(edge, exp2q(log2u(static_cast<u32>(INC_LIMIT) - fk) - L_INC_NY01, 31));
            }
        }
        v.edge[k] = edge;
        if (!edge) { v.y1[k] = v.y2[k] = 0; v.mc[k] = 0; v.sn[k] = 0; continue; }
        i32 h, c; half_angle(fk, h, c);
        const i32 sn = 2 * mul(h, c);                   // sin th
        v.sn[k] = sn;
        if (fk < static_cast<u32>(INC_SIXTH)) {
            v.mc[k] = TWO_1MR[k] + mul(mul(h, h), POLE[k]) * 4;     // 2 - 2 r cos th = 2 (1 - r) + 4 r h^2
        } else {
            v.mc[k] = mul(POLE[k], cosine(fk) * 2);    // 2 r cos th in Q30 = r cos th in Q31
            v.high |= 1u << k;
        }
        v.leps[k] = sar(softplus2(L_EPS[k] - 2 * log2q(sn, 31)), 1);
    }
}
// |d| folded onto the FM lattice spacing sp: distance to the nearest lattice line (Q26).
i32 fold(i32 d, i32 sp) {
    if (d >= sp) {
        const u32 n = exp2u(log2u(static_cast<u32>(d)) - log2u(static_cast<u32>(sp)));
        d = static_cast<i32>(static_cast<u32>(d) - n * static_cast<u32>(sp));
        if (d < 0) d += sp;
        if (d >= sp) d -= sp;
    }
    return 2 * d > sp ? sp - d : d;
}
// log2(1 + X^2), X = 2 d f0 / bw: how far a mode at distance d (Q26, in notes) sits off the lattice, in bandwidths.
inline i32 off_lattice(i32 d, i32 lhz, i32 lbw) {
    return d ? softplus2(2 * (ONE_LOG + log2q(d, 26) + lhz - lbw)) : 0;
}
// Make-up gain per mode: modes moved off the FM's harmonic lattice catch less of it (at most 18 dB either way),
// and modes moved up get up to 12 dB more.
void setup_makeup(Voice& v, i32 ratio_word) {
    const i32 linc = log2u(v.setup_inc);
    const i32 lhz = linc + L_FS - 32 * ONE_LOG;
    const i32 sp = (ratio_word > RATIO_MIN ? ratio_word : MAX) >> 5;   // Q26
    for (unsigned k = 0; k < MODES; ++k) {
        const i32 dm = fold(RM_DIST[k], sp);
        const u32 rel = exp2u(v.lfk[k] - linc + 26 * ONE_LOG);
        const i32 ratio_k = rel > 0x7fffffffu ? MAX : static_cast<i32>(rel);
        const i32 da = fold(absolute(ratio_k - (1 << 26)), sp);
        i32 lmk = clamp(sar(off_lattice(da, lhz, L_BW[k]) - off_lattice(dm, lhz, L_BW[k]), 1),
                        -3 * ONE_LOG, 3 * ONE_LOG);
        const i32 up = v.lfk[k] - linc - L_RM[k];
        if (up > 0) { const i32 t = mul(up, UP_POWER); lmk += t < 2 * ONE_LOG ? t : 2 * ONE_LOG; }
        v.mk_target[k] = exp2q(lmk, 25);
        if (!v.mk[k]) v.mk[k] = v.mk_target[k];
    }
    v.gx_dirty = 1;
}
// Each mode's input gain: the reference's b = (1 - r) |1 - r e^(2 j th)| ra RES_GAIN edge make-up MODES, in log2.
void update_b(Voice& v) {
    for (unsigned k = 0; k < MODES; ++k)
        v.b[k] = v.edge[k] && v.wk[k]
            ? mul(mul(exp2q(L_B[k] + log2q(v.sn[k], 31) + v.leps[k] + log2q(v.mk[k], 25), 31), v.edge[k]), v.wk[k])
            : 0;
    v.gx_dirty = 0;
}

// ---------------------------------------------------------------- the onset
// The reference's shortest attack: the level rises 3 ms in a straight line from where the note found it, eased in.
// Each stage applies its square root; returns the gain after this 16-sample step.
i32 onset_step(Voice& v) {
    if (!v.ramping) return MAX;
    v.att_u = v.att_u >= MAX - ATTACK_STEP ? MAX : v.att_u + ATTACK_STEP;
    const u32 j = v.att_j++;
    const i32 w = j < sizeof EASE / sizeof EASE[0] ? EASE[j] : MAX;
    if (v.att_u == MAX && w == MAX) { v.ramping = 0; return MAX; }
    return v.att_g0 + mul(sqrt31(v.att_u) - v.att_g0, w);
}

// ---------------------------------------------------------------- FM core
// One 16-sample step at 2x: op2 with self-feedback phase-modulates the carrier through two one-poles; the drop
// multiplies both increments. Writes s0 + s1 of the half-band (2x the reference's x).
void core_step(Voice& v, i32* x, u32 base, i32 ratio) {
    u32 inc0 = base >> 1;                              // 2x rate
    if (v.sweep_oct) {
        if (!v.sweep_u) {
            inc0 = exp2u(log2u(inc0) + v.sweep_oct);   // nothing of the drop done yet
        } else if (v.sweep_u < MAX) {
            const i32 lu = log2q(v.sweep_u, 31);
            const i32 left = MAX - exp2q(lu + mul(lu, SWEEP_E), 31);   // 1 - u^e
            inc0 = exp2u(log2u(inc0) + mul(v.sweep_oct, left));
        }
        if (inc0 > static_cast<u32>(INC_2X_LIMIT)) inc0 = static_cast<u32>(INC_2X_LIMIT);
        if (v.sweep_u < MAX) {                         // u = j du; the drop never takes more than 256 steps
            const u32 u = static_cast<u32>(v.sweep_du >> 4) * ++v.sweep_j;   // Q27
            v.sweep_u = u >= (1u << 27) || v.sweep_j >= 256 ? MAX : static_cast<i32>(u << 4);
        }
    }
    const u32 inc2 = static_cast<u32>(mul(static_cast<i32>(inc0), ratio));
    const i32 depth = DEPTH0 + mul(DEPTH_BITE, v.bite);   // Q29
    v.bite = mul(v.bite, BITE_DECAY);
    const i32 diff = static_cast<i32>(inc0 - v.inc_prev);
    const u32 dinc = static_cast<u32>(diff >= 0 ? diff >> 5 : -((-diff) >> 5));
    u32 inc = v.inc_prev, ph0 = v.ph0, ph2 = v.ph2;
    i32 s2p = v.s2p, l1 = v.l1, l2 = v.l2;
    i32 car[2 * STEP];
    for (unsigned k = 0; k < 2 * STEP; ++k) {
        ph2 += inc2;
        const i32 s2 = sine(ph2 + static_cast<u32>(mul(s2p, FB_PHASE)));
        const i32 d = clamp(s2 - s2p, -(1 << 30), (1 << 30) - 1);
        s2p = s2;
        const i32 m = l1;
        l1 = half(l1) + half(d);
        const i32 u = l2;
        l2 = half(l2) + half(clamp(mul29(m, depth), -(1 << 30), (1 << 30) - 1));
        inc += dinc;
        car[k] = sar(sine(ph0), 3);                    // the carrier at 1/16 full scale
        ph0 += inc + static_cast<u32>(u);              // 0.25 u cycles: u in Q30
    }
    v.ph0 = ph0; v.ph2 = ph2; v.s2p = s2p; v.l1 = l1; v.l2 = l2; v.inc_prev = inc0;
    for (unsigned n = 0; n < STEP; ++n) {              // 2x -> 1x
        i32 s1 = car[2 * n], s0 = car[2 * n + 1], t;
        t = mul(s0 - v.hy[0], HALFBAND[0]) + v.hx[0]; v.hx[0] = s0; v.hy[0] = t; s0 = t;
        t = mul(s0 - v.hy[2], HALFBAND[2]) + v.hx[2]; v.hx[2] = s0; v.hy[2] = t; s0 = t;
        t = mul(s1 - v.hy[1], HALFBAND[1]) + v.hx[1]; v.hx[1] = s1; v.hy[1] = t; s1 = t;
        t = mul(s1 - v.hy[3], HALFBAND[3]) + v.hx[3]; v.hx[3] = s1; v.hy[3] = t; s1 = t;
        x[n] = s0 + s1;
    }
}

// ---------------------------------------------------------------- MODAL
// Adds each mode (2^MODE_SHIFT x) into acc. With STRIKE, the pulse goes into the modes during the first samples of
// the note, shared between the audible modes by sqrt(ra).
template <bool HIGH> inline void mode_run(i32* acc, const i32* x, i32& y1r, i32& y2r, i32 c, i32 eta, i32 b,
                                          unsigned from, unsigned to) {
    i32 y1 = y1r, y2 = y2r;
    for (unsigned n = from; n < to; ++n) {
        const i32 y = (HIGH ? mul30(y1, c) : 2 * y1 - mul(y1, c)) - y2 + mul(y2, eta) + mul(b, x[n]);
        y2 = y1; y1 = y;
        acc[n] += y;
    }
    y1r = y1; y2r = y2;
}
void modes_block(Voice& v, const i32* x, i32* acc, bool strike) {
    i32 gp[MODES] = {0, 0, 0, 0, 0, 0, 0, 0};
    if (strike) {
        i32 term[MODES], wsum = 0;
        for (unsigned k = 0; k < MODES; ++k) {
            term[k] = v.edge[k] && v.wk[k] ? mul(mul(SQRT_RA[k], v.edge[k]), v.wk[k]) : 0;
            wsum += term[k] >> 3;                      // Q28
        }
        const i32 lw = wsum < 268 ? 0 : log2q(wsum, 28);
        for (unsigned k = 0; k < MODES; ++k)
            gp[k] = term[k] ? exp2q(L_BP[k] + log2q(v.sn[k], 31) + log2q(term[k], 31) - lw, 31) : 0;
    }
    const unsigned pulse = sizeof STRIKE / sizeof STRIKE[0];
    for (unsigned k = 0; k < MODES; ++k) {
        if (!v.edge[k]) continue;
        i32& y1 = v.y1[k];
        i32& y2 = v.y2[k];
        if (!v.wk[k] && !y1 && !y2) continue;          // not fed and silent
        const i32 c = v.mc[k], eta = ETA[k], b = v.b[k];
        const bool high = (v.high >> k) & 1;
        unsigned n = 0;
        if (gp[k]) {                                   // STRIKE: the pulse joins the drive
            const i32 p = gp[k];
            i32 s1 = y1, s2 = y2;
            for (; n < pulse; ++n) {
                const i32 y = (high ? mul30(s1, c) : 2 * s1 - mul(s1, c)) - s2 + mul(s2, eta) + mul(b, x[n])
                            + mul(p, STRIKE[n]);
                s2 = s1; s1 = y;
                acc[n] += y;
            }
            y1 = s1; y2 = s2;
        }
        if (high) mode_run<true>(acc, x, y1, y2, c, eta, b, n, opxy::block_frames);
        else mode_run<false>(acc, x, y1, y2, c, eta, b, n, opxy::block_frames);
        if (!v.wk[k] && absolute(y1) < FLUSH && absolute(y2) < FLUSH) y1 = y2 = 0;
    }
}

void clear(Voice& voice) {
    u32* words = reinterpret_cast<u32*>(&voice);
    for (unsigned i = 0; i < sizeof(Voice) / sizeof(u32); ++i) words[i] = 0;
}

// Taps for the machine's own tests: each stage of the last block. Null in the device and preview builds.
struct Taps { i32 core[64], drive[64], mix[64], out[64]; };

inline void process(Voice& v, opxy::Output output, opxy::Parameters parameters, opxy::Pitch pitch, Taps* taps) {
    // ---- knobs
    const i32 drop = knob_word(parameters[0]), ratio_word = knob_word(parameters[1]);
    const i32 stretch = knob_word(parameters[2]), modes = knob_word(parameters[3]);
    bool remode = false, remakeup = false;
    if (!v.knobs_seen || drop != v.knob[0]) set_drop(v, drop);
    if (!v.knobs_seen || stretch != v.knob[2]) { set_stretch(v, stretch); remode = true; }
    if (!v.knobs_seen || modes != v.knob[3]) { set_modes(v, modes); v.gx_dirty = 1; }
    if (!v.knobs_seen || ratio_word != v.knob[1]) remakeup = true;
    v.knob[0] = drop; v.knob[1] = ratio_word; v.knob[2] = stretch; v.knob[3] = modes; v.knobs_seen = 1;
    // ---- pitch: set up again when it moves more than about 3.4 cents (glide, bend, transpose)
    const u32 inc = pitch[0];
    const u32 moved = inc > v.setup_inc ? inc - v.setup_inc : v.setup_inc - inc;
    if (!v.setup_inc || moved > (v.setup_inc >> 9)) { setup_pitch(v, inc); remode = true; }
    if (remode) { setup_modes(v); remakeup = true; v.gx_dirty = 1; }
    if (remakeup) setup_makeup(v, ratio_word);
    for (unsigned k = 0; k < MODES; ++k) {             // make-up eases ~20 ms
        const i32 d = v.mk_target[k] - v.mk[k];
        if (!d) continue;
        v.mk[k] = absolute(d) < 256 ? v.mk_target[k] : v.mk[k] + mul(d, KK_MAKEUP);
        v.gx_dirty = 1;
    }
    if (v.gx_dirty) update_b(v);
    // ---- note-on
    const bool strike = v.note_pending != 0;
    if (strike) {
        v.note_pending = 0;
        const u32 base = pitch[0] >> 1;
        if (v.sweep_oct) v.inc_prev = exp2u(log2u(base) + v.sweep_oct);   // start where the drop starts
        else if (!v.inc_prev) v.inc_prev = base;
    }
    // ---- FM core and the onset, per 16 samples
    i32 x[opxy::block_frames], gains[opxy::block_frames];
    const bool shaped = v.ramping || v.gain != MAX;
    for (unsigned j = 0; j < STEPS; ++j) {
        core_step(v, x + j * STEP, pitch[j * STEP], ratio_word);
        if (shaped) {
            const i32 e0 = v.gain, e1 = onset_step(v);
            const i32 d = half(e1) - half(e0);
            for (unsigned n = 0; n + 1 < STEP; ++n) gains[j * STEP + n] = e0 + 2 * mul(d, static_cast<i32>(n + 1) << 27);
            gains[j * STEP + STEP - 1] = e1;
            v.gain = e1;
        }
    }
    if (taps) for (unsigned n = 0; n < opxy::block_frames; ++n) taps->core[n] = x[n];
    // ---- into the resonator: both fixed low-passes, the high-pass (with the drive and dry gains), presence
    if (shaped) for (unsigned n = 0; n < opxy::block_frames; ++n) x[n] = mul(x[n], gains[n]);
    {
        Biquad lp1 = v.lp1, lp2 = v.lp2, hp = v.hp1, pk = v.pk;    // held in registers through the loop
        const i32 hc[4] = {v.hp_c[0], v.hp_c[1], v.hp_c[2], v.hp_c[3]};
        const i32 pc[4] = {v.pk_c[0], v.pk_c[1], v.pk_c[2], v.pk_c[3]};
        for (unsigned n = 0; n < opxy::block_frames; ++n)
            x[n] = presence(pk, pc, highpass(hp, hc[0], hc, lowpass(lp2, lowpass(lp1, x[n]))));
        v.lp1 = lp1; v.lp2 = lp2; v.hp1 = hp; v.pk = pk;
    }
    if (taps) for (unsigned n = 0; n < opxy::block_frames; ++n) taps->drive[n] = x[n];
    // ---- MODAL, mixed with the dry drive
    i32 acc[opxy::block_frames];
    for (unsigned n = 0; n < opxy::block_frames; ++n) acc[n] = 0;
    modes_block(v, x, acc, strike);
    for (unsigned n = 0; n < opxy::block_frames; ++n) acc[n] = x[n] + sar(acc[n], MODE_SHIFT);
    if (taps) for (unsigned n = 0; n < opxy::block_frames; ++n) taps->mix[n] = acc[n];
    if (shaped) for (unsigned n = 0; n < opxy::block_frames; ++n) acc[n] = mul(acc[n], gains[n]);
    // ---- after the resonator
    {
        Biquad hp = v.hp2, hs = v.hs;
        const i32 hc[4] = {v.hp_c[0], v.hp_c[1], v.hp_c[2], v.hp_c[3]};
        const i32 sc[5] = {v.hs_c[0], v.hs_c[1], v.hs_c[2], v.hs_c[3], v.hs_c[4]};
        for (unsigned n = 0; n < opxy::block_frames; ++n) output[n] = shelf(hs, sc, highpass(hp, hc[1], hc, acc[n]));
        v.hp2 = hp; v.hs = hs;
    }
    if (taps) for (unsigned n = 0; n < opxy::block_frames; ++n) taps->out[n] = output[n];
}
} // namespace

inline void initialize(Voice& voice, Shared&, u32) { clear(voice); }

// Each note: the oscillators and filters keep running (as in the reference); the drop, BITE and STRIKE start again,
// and the onset rises from wherever the level is (from silence on a fresh voice).
inline void start(Voice& voice, Shared&, u32) {
    voice.note_pending = 1;
    voice.sweep_j = 0;
    voice.sweep_u = 0;
    voice.bite = MAX;
    const i32 level = voice.gain == MAX ? MAX : mul(voice.gain, voice.gain);
    voice.ramping = level != MAX;
    voice.att_u = level;
    voice.att_g0 = voice.gain;
    voice.att_j = 0;
}

inline void destroy(Voice&, Shared&, u32) {}

inline void render(Voice& voice, Shared&, u32, opxy::Output output, opxy::Parameters parameters, opxy::Pitch pitch) {
    process(voice, output, parameters, pitch, static_cast<Taps*>(0));
}

} // namespace rings
